// ── Detect input type from chat message & binary attachments ───────
const item = $input.first();
const message = (item.json.chatInput || '').trim();
const sessionId = item.json.sessionId || 'default';
const binary = item.binary || {};
const binaryKeys = Object.keys(binary);

let inputType = 'question'; // default: treat as follow-up Q&A
let meta = {};

// ── 1. File attachment (CSV or Excel)
if (binaryKeys.length > 0) {
  const key = binaryKeys[0];
  const mimeType = binary[key]?.mimeType || '';
  if (
    mimeType.includes('csv') ||
    mimeType.includes('excel') ||
    mimeType.includes('spreadsheetml') ||
    mimeType.includes('text/plain')
  ) {
    inputType = 'file';
    meta = { binaryKey: key, mimeType, fileName: binary[key]?.fileName || 'upload' };
  }
}

// ── 2. Google Sheets URL
else if (/https:\/\/docs\.google\.com\/spreadsheets/i.test(message)) {
  inputType = 'sheets';
  const idMatch = message.match(/\/d\/([a-zA-Z0-9-_]+)/);
  const gidMatch = message.match(/[#&?]gid=([0-9]+)/);
  if (!idMatch) throw new Error('Could not extract Google Sheets ID from URL.');
  meta = {
    spreadsheetId: idMatch[1],
    gid: gidMatch ? gidMatch[1] : '0',
    rawUrl: message
  };
}

// ── 3. REST API URL
else if (/^https?:\/\//i.test(message) && !message.includes('docs.google.com')) {
  inputType = 'api';
  // Support optional jsonPath suffix: "https://api.example.com/data >> data.items"
  const parts = message.split('>>');
  meta = {
    apiUrl: parts[0].trim(),
    jsonPath: parts[1] ? parts[1].trim() : ''
  };
}

// ── 4. SQL query
else if (/^sql:/i.test(message)) {
  inputType = 'sql';
  meta = { sqlQuery: message.replace(/^sql:/i, '').trim() };
}

return [{ json: { message, sessionId, inputType, meta, binary } }];

// ── Branch: Parse CSV or Excel file attachment ─────────────────────
const item = $input.first();
const { message, sessionId, meta } = item.json;
const binary = item.binary || {};
const binaryKey = meta.binaryKey;
const mimeType = meta.mimeType || '';

if (!binary[binaryKey]) throw new Error('Binary file not found in attachment.');

const buf = Buffer.from(binary[binaryKey].data, 'base64');
let csvText = '';

// For CSV/TXT files, decode directly
if (mimeType.includes('csv') || mimeType.includes('text/plain')) {
  csvText = buf.toString('utf-8');
} else {
  // Excel files: we cannot parse XLSX natively in n8n Code node without a library.
  // Return a helpful error directing to use the Spreadsheet File node instead.
  throw new Error(
    'Excel (.xlsx/.xls) files require the "Spreadsheet File" node to parse. '
    + 'Please use the dedicated Excel branch, or convert your file to CSV first.'
  );
}

function csvToMarkdown(text, maxRows = 300) {
  const lines = text.trim().split('\n').filter(l => l.trim());
  if (!lines.length) return { table: '(empty file)', headers: [], rowCount: 0 };
  const splitter = lines[0].includes('\t') ? '\t' : ',';
  const headers = lines[0].split(splitter).map(h => h.trim().replace(/^"|"$/g, ''));
  const dataRows = lines.slice(1, maxRows + 1);
  const rows = dataRows.map(l => l.split(splitter).map(v => v.trim().replace(/^"|"$/g, '')));
  const head = `| ${headers.join(' | ')} |`;
  const sep  = `| ${headers.map(() => '---').join(' | ')} |`;
  const body = rows.map(r => `| ${r.join(' | ')} |`).join('\n');
  return { table: [head, sep, body].join('\n'), headers, rowCount: lines.length - 1 };
}

const { table, headers, rowCount } = csvToMarkdown(csvText);
const dataMarkdown = `**Source:** CSV File (${meta.fileName})\n**Rows:** ${rowCount}\n**Columns:** ${headers.join(', ')}\n\n${table}`;

return [{
  json: {
    sessionId,
    message: message || 'Data loaded. Please analyse it.',
    dataLoaded: true,
    dataLabel: `${meta.fileName} (${rowCount} rows × ${headers.length} cols)`,
    dataMarkdown,
    rowCount,
    columnCount: headers.length,
    headers
  }
}];

// ── Branch: Extract binary from Excel via n8n Spreadsheet node prep ─
// This node prepares the binary so the Spreadsheet File node can read it.
const item = $input.first();
const { message, sessionId, meta } = item.json;
return [{
  json: { message, sessionId, meta },
  binary: item.binary
}];

// ── Convert Excel rows → markdown table ────────────────────────────
const rows = $input.all();
if (!rows.length) throw new Error('Excel file appears to be empty.');

const meta   = $('Prep Excel Binary').first().json.meta;
const sessionId = $('Prep Excel Binary').first().json.sessionId;
const message   = $('Prep Excel Binary').first().json.message;

const headers = Object.keys(rows[0].json);
const maxRows = Math.min(rows.length, 300);

const head = `| ${headers.join(' | ')} |`;
const sep  = `| ${headers.map(() => '---').join(' | ')} |`;
const body = rows.slice(0, maxRows).map(r =>
  `| ${headers.map(h => String(r.json[h] ?? '')).join(' | ')} |`
).join('\n');

const table = [head, sep, body].join('\n');
const dataMarkdown = `**Source:** Excel File (${meta.fileName})\n**Rows:** ${rows.length}\n**Columns:** ${headers.join(', ')}\n\n${table}`;

return [{
  json: {
    sessionId,
    message: message || 'Data loaded. Please analyse it.',
    dataLoaded: true,
    dataLabel: `${meta.fileName} (${rows.length} rows × ${headers.length} cols)`,
    dataMarkdown,
    rowCount: rows.length,
    columnCount: headers.length,
    headers
  }
}];

// ── Branch: Google Sheets → build CSV export URL ───────────────────
const { message, sessionId, meta } = $input.first().json;
if (!meta.spreadsheetId) throw new Error('Could not extract Google Sheets ID.');
const csvUrl = `https://docs.google.com/spreadsheets/d/${meta.spreadsheetId}/export?format=csv&gid=${meta.gid}`;
return [{ json: { message, sessionId, meta, csvUrl } }];

// ── Parse Sheets CSV → markdown ────────────────────────────────────
const prep = $('Prep Sheets URL').first().json;
const rawText = $input.first().json.data || '';
const text = typeof rawText === 'string' ? rawText : JSON.stringify(rawText);

function csvToMarkdown(text, maxRows = 300) {
  const lines = text.trim().split('\n').filter(l => l.trim());
  if (!lines.length) return { table: '(empty)', headers: [], rowCount: 0 };
  const headers = lines[0].split(',').map(h => h.trim().replace(/^"|"$/g, ''));
  const rows = lines.slice(1, maxRows + 1).map(l => l.split(',').map(v => v.trim().replace(/^"|"$/g, '')));
  const head = `| ${headers.join(' | ')} |`;
  const sep  = `| ${headers.map(() => '---').join(' | ')} |`;
  const body = rows.map(r => `| ${r.join(' | ')} |`).join('\n');
  return { table: [head, sep, body].join('\n'), headers, rowCount: lines.length - 1 };
}

const { table, headers, rowCount } = csvToMarkdown(text);
const dataMarkdown = `**Source:** Google Sheets\n**ID:** ${prep.meta.spreadsheetId}\n**Rows:** ${rowCount}\n**Columns:** ${headers.join(', ')}\n\n${table}`;

return [{
  json: {
    sessionId: prep.sessionId,
    message: prep.message || 'Data loaded.',
    dataLoaded: true,
    dataLabel: `Google Sheets — ${rowCount} rows × ${headers.length} cols`,
    dataMarkdown,
    rowCount,
    columnCount: headers.length,
    headers
  }
}];

// ── Branch: REST API fetch prep ────────────────────────────────────
const { message, sessionId, meta } = $input.first().json;
if (!meta.apiUrl) throw new Error('No API URL found.');
return [{ json: { message, sessionId, meta, apiUrl: meta.apiUrl } }];

// ── Parse REST API JSON → markdown table ───────────────────────────
const prep = $('Prep API Request').first().json;
let data = $input.first().json;

// Resolve JSON path if provided (e.g. "data.items")
const jsonPath = prep.meta.jsonPath || '';
if (jsonPath) {
  const keys = jsonPath.split('.');
  for (const k of keys) { data = data?.[k]; }
}

const arr = Array.isArray(data) ? data : (data ? [data] : []);
if (!arr.length) throw new Error('API returned no records. Check the URL or JSON path.');

const headers = Object.keys(arr[0]);
const maxRows = Math.min(arr.length, 300);
const head = `| ${headers.join(' | ')} |`;
const sep  = `| ${headers.map(() => '---').join(' | ')} |`;
const body = arr.slice(0, maxRows).map(r =>
  `| ${headers.map(h => String(r[h] ?? '')).join(' | ')} |`
).join('\n');
const table = [head, sep, body].join('\n');

const dataMarkdown = `**Source:** REST API (${prep.apiUrl})\n**Records:** ${arr.length}\n**Fields:** ${headers.join(', ')}\n\n${table}`;

return [{
  json: {
    sessionId: prep.sessionId,
    message: prep.message || 'Data loaded.',
    dataLoaded: true,
    dataLabel: `REST API — ${arr.length} records × ${headers.length} fields`,
    dataMarkdown,
    rowCount: arr.length,
    columnCount: headers.length,
    headers
  }
}];

// ── Convert SQL result rows → markdown table ───────────────────────
const prep = $('Route Input').first();
const sqlMeta = $('Detect Input Type').first().json;
const rows = $input.all();

if (!rows.length) throw new Error('SQL query returned no rows.');

const headers = Object.keys(rows[0].json);
const maxRows = Math.min(rows.length, 300);
const head = `| ${headers.join(' | ')} |`;
const sep  = `| ${headers.map(() => '---').join(' | ')} |`;
const body = rows.slice(0, maxRows).map(r =>
  `| ${headers.map(h => String(r.json[h] ?? '')).join(' | ')} |`
).join('\n');
const table = [head, sep, body].join('\n');

const sqlQuery = sqlMeta.json?.meta?.sqlQuery || '(query not captured)';
const dataMarkdown = `**Source:** SQL (Postgres)\n**Query:** \`${sqlQuery}\`\n**Rows:** ${rows.length}\n**Columns:** ${headers.join(', ')}\n\n${table}`;

return [{
  json: {
    sessionId: sqlMeta.json.sessionId,
    message: sqlMeta.json.message || 'Data loaded.',
    dataLoaded: true,
    dataLabel: `SQL Query — ${rows.length} rows × ${headers.length} cols`,
    dataMarkdown,
    rowCount: rows.length,
    columnCount: headers.length,
    headers
  }
}];

// ── Session Memory: Store & Retrieve data context + conversation history ──
// Uses n8n workflow static data keyed by sessionId.
// Each session tracks:
//   - dataMarkdown  : the loaded dataset as a markdown table
//   - dataLabel     : human-readable source label
//   - history       : array of { role, content } for multi-turn memory
//   - lastUpdated   : ISO timestamp of last activity
//
// History window: keeps last MAX_HISTORY turns to avoid token overflow.
// For production scale, swap staticData for a Redis or Postgres node.

const MAX_HISTORY = 20; // max user+assistant pairs stored = 40 messages

const item = $input.first().json;
const sessionId = item.sessionId || 'default';

const staticData = $getWorkflowStaticData('global');
if (!staticData.sessions) staticData.sessions = {};

let session = staticData.sessions[sessionId] || {
  dataMarkdown: null,
  dataLabel: null,
  headers: [],
  rowCount: 0,
  history: [],
  lastUpdated: null
};

// ── Update dataset if a new one was just loaded ──
if (item.dataLoaded && item.dataMarkdown) {
  session.dataMarkdown = item.dataMarkdown;
  session.dataLabel    = item.dataLabel;
  session.headers      = item.headers || [];
  session.rowCount     = item.rowCount || 0;
  // Reset history when a brand new dataset is loaded so context stays clean
  session.history      = [];
}

// ── Retrieve existing history for this turn ──
const history = session.history || [];

// ── Persist updated session back to static data ──
session.lastUpdated = new Date().toISOString();
staticData.sessions[sessionId] = session;

const hasData = !!session.dataMarkdown;

return [{
  json: {
    sessionId,
    message:      item.message || '',
    dataLoaded:   item.dataLoaded || false,
    hasData,
    dataMarkdown: session.dataMarkdown || '',
    dataLabel:    session.dataLabel || 'No dataset loaded yet',
    headers:      session.headers || [],
    rowCount:     session.rowCount || 0,
    history,          // ← full history array passed forward
    maxHistory:   MAX_HISTORY
  }
}];

// ── Build system prompt + full conversation history for OpenRouter ──
// Structure sent to OpenRouter:
//   [ system, ...history, user ]
// On data-load turns: history is reset, assistant greets with dataset summary.
// On question turns: full rolling history is included for multi-turn context.

const {
  message, hasData, dataMarkdown, dataLabel,
  dataLoaded, history, sessionId, rowCount, headers
} = $input.first().json;

let systemPrompt = '';
let userMessage  = message;
let historyToSend = history || [];

if (dataLoaded && hasData) {
  // ── New dataset just loaded ──
  // Send the dataset in the user turn; ask the LLM to greet & suggest questions.
  systemPrompt = `You are DataLens AI, an expert data analyst.
The user has just loaded a new dataset into the chat. Your job:
1. Confirm what was loaded (source name, row count, column names)
2. Highlight 2-3 immediately interesting things you notice about the schema
3. Suggest 5 smart analytical questions the user could ask
Be concise, friendly, and formatted in clean markdown.`;

  userMessage = `Dataset loaded: ${dataLabel}\nRows: ${rowCount} | Columns: ${(headers||[]).join(', ')}\n\nFull dataset preview (up to 300 rows):\n\n${dataMarkdown}`;

  // Clear history for clean context on new dataset
  historyToSend = [];

} else if (hasData) {
  // ── Follow-up analytical question ──
  systemPrompt = `You are DataLens AI, an expert data analyst embedded in a chat interface.

The user has loaded the following dataset (available throughout this conversation):
--- DATASET START ---
${dataMarkdown}
--- DATASET END ---

Guidelines:
- Answer questions accurately and only based on the data above
- Spot trends, patterns, outliers, correlations, and anomalies
- Produce ASCII charts, ranked lists, or markdown tables when helpful
- Reference prior conversation turns naturally when relevant
- Suggest follow-up analyses the user may not have considered
- If the data is insufficient to answer, say so clearly
- Keep responses concise and formatted in clean markdown`;

  // userMessage is the raw question — history carries prior turns

} else {
  // ── No data loaded yet ──
  systemPrompt = `You are DataLens AI, a chat-based data analysis assistant.
The user has NOT loaded any dataset yet. Remind them how to get started:
- 📎 Attach a CSV or Excel file directly in chat
- 🔗 Paste a public Google Sheets URL
- 🌐 Paste a REST API endpoint URL (optionally add >> jsonPath)
- 🗄 Type sql: followed by a SELECT query (Postgres credentials required in workflow)
Be friendly and brief.`;
  historyToSend = [];
}

// ── Assemble the full messages array ──
// Format: [system] + [...history pairs] + [current user message]
const messages = [
  { role: 'system', content: systemPrompt },
  ...historyToSend,
  { role: 'user', content: userMessage }
];

return [{
  json: {
    messages,
    model: 'anthropic/claude-3.5-haiku',
    sessionId,
    userMessage   // passed through so Extract Reply can save it to history
  }
}];

// ── Extract LLM reply & save turn to session history ───────────────
// After every successful LLM response, we:
//   1. Extract the assistant's reply text
//   2. Append { role: 'user', content } and { role: 'assistant', content }
//      to the session's history in static data
//   3. Trim history to MAX_HISTORY pairs to prevent token overflow
//   4. Return { output: reply } for the Chat Trigger to display

const MAX_HISTORY = 20; // same cap as Session Memory node

const response   = $input.first().json;
const buildData  = $('Build Prompt').first().json;
const sessionId  = buildData.sessionId || 'default';
const userMessage = buildData.userMessage || '';

let reply = '';
try {
  reply = response.choices[0].message.content || 'No response generated.';
} catch (e) {
  if (response.error) {
    reply = `❌ **OpenRouter Error:** ${response.error.message || JSON.stringify(response.error)}`;
  } else {
    reply = `❌ Unexpected response format: ${JSON.stringify(response).slice(0, 300)}`;
  }
}

// ── Persist this turn into session history ──
const staticData = $getWorkflowStaticData('global');
if (!staticData.sessions) staticData.sessions = {};
if (!staticData.sessions[sessionId]) staticData.sessions[sessionId] = { history: [] };

const session = staticData.sessions[sessionId];
if (!session.history) session.history = [];

// Append user turn then assistant turn
session.history.push({ role: 'user',      content: userMessage });
session.history.push({ role: 'assistant', content: reply });

// Trim to rolling window: keep last MAX_HISTORY pairs = MAX_HISTORY*2 messages
if (session.history.length > MAX_HISTORY * 2) {
  session.history = session.history.slice(-(MAX_HISTORY * 2));
}

staticData.sessions[sessionId] = session;

// ── Build footer with usage stats ──
const usage = response.usage || {};
let footer = '';
if (usage.total_tokens) {
  footer = `\n\n---\n*Model: ${response.model || 'unknown'} · Tokens: ${usage.prompt_tokens || 0} in + ${usage.completion_tokens || 0} out = ${usage.total_tokens} total · History turns: ${session.history.length / 2}*`;
}

return [{ json: { output: reply + footer } }];
